(()=>{'use strict';
const key=([a,b,n])=>[a,b].sort((x,y)=>x-y).join(',')+','+n;
// Three carbons in every mode, including the carbonyl carbon where present.
function buildMode(kind){const alcohol=kind===0,acid=kind===2,group=alcohol?[3]:acid?[2,3,4]:[2,3],labels=['O','C=O','O=C–O'],symbols=alcohol?['C','C','C','O',...Array(8).fill('H')]:acid?['C','C','C','O','O',...Array(6).fill('H')]:['C','C','C','O',...Array(6).fill('H')],other=alcohol?[0,1,2]:[0,1],states=[],count=other.length+1;
for(let slot=0;slot<count;slot++){const order=other.slice();order.splice(slot,0,...(alcohol?[3]:acid?[2,4]:[2]));const xs=order.length===4?[140,260,380,500]:[180,330,480],positions=symbols.map(()=>[0,0]),bonds=[];order.forEach((id,j)=>{positions[id]=[xs[j],240];if(j)bonds.push([order[j-1],id,1]);});if(!alcohol){positions[3]=[positions[2][0],100];bonds.push([2,3,2]);}
const hStart=alcohol?4:acid?5:4;other.forEach((c,j)=>{for(let h=0;h<2;h++){const id=hStart+j*2+h;positions[id]=[positions[c][0],h?350:130];bonds.push([c,id,1]);}});const hLeft=symbols.length-2,hRight=symbols.length-1;positions[hLeft]=[50,240];positions[hRight]=[610,240];bonds.push([hLeft,order[0],1],[order.at(-1),hRight,1]);const name=alcohol?(slot===0||slot===3?'Propan-1-ol · alcohol':'Methoxyethane · ether'):acid?['Ethyl methanoate · ester','Methyl ethanoate · ester','Propanoic acid · carboxylic acid'][slot]:(slot===1?'Propanone · ketone':'Propanal · aldehyde');states.push({positions,bonds,name});}
return {id:['alcohol-ether','aldehyde-ketone','acid-ester'][kind],title:['Alcohol ↔ ether','Aldehyde ↔ ketone','Carboxylic acid ↔ ester'][kind],general:['CₙH₂ₙ₊₂O','CₙH₂ₙO','CₙH₂ₙO₂'][kind],formula:['C₃H₈O','C₃H₆O','C₃H₆O₂'][kind],symbols,group,label:labels[kind],states,initial:count-1};}
const cases=[0,1,2].map(buildMode);
function counts(c){return c.symbols.reduce((r,s)=>(r[s]=(r[s]||0)+1,r),{});}
function frame(c,value){const v=Math.max(0,Math.min(c.states.length-1,value)),lo=Math.floor(v),hi=Math.min(lo+1,c.states.length-1),t=v-lo,a=c.states[lo],b=c.states[hi];return {value:v,positions:a.positions.map(([x,y],i)=>[x+(b.positions[i][0]-x)*t,y]),bonds:[...new Set([...a.bonds,...b.bonds].map(key))].map(k=>{const before=a.bonds.some(e=>key(e)===k),after=b.bonds.some(e=>key(e)===k);return {edge:k.split(',').map(Number),opacity:before&&after?1:before?1-t:t,changing:before!==after};}),settled:Math.abs(v-Math.round(v))<1e-6,name:c.states[Math.round(v)].name};}
function dragValue(c,x){const anchor=c.group[0],xs=c.states.map(s=>s.positions[anchor][0]);if(x<=xs[0])return 0;if(x>=xs.at(-1))return xs.length-1;let j=0;while(xs[j+1]<x)j++;return j+(x-xs[j])/(xs[j+1]-xs[j]);}
if(typeof module!=='undefined'&&module.exports)module.exports={cases,frame,counts,dragValue};if(typeof document==='undefined')return;
const root=document.getElementById('gf-game');if(!root)return;let drag=null;const values=cases.map(c=>c.initial),panels=document.getElementById('gf-panels');
panels.innerHTML='<div class="gf-modes" role="group" aria-label="Isomer pair">'+cases.map((c,i)=>`<button id="gf-mode-${i}" type="button" aria-pressed="${i===0}" aria-controls="gf-panel-${i}">${c.title}</button>`).join('')+'</div>'+cases.map((c,i)=>`<section id="gf-panel-${i}" class="gf-panel" aria-labelledby="gf-title-${i}" ${i?'hidden':''}><div class="gf-heading"><h3 id="gf-title-${i}">${c.title}</h3><div class="gf-general"><strong>${c.general}</strong><span>Three-carbon framework</span></div></div><div class="gf-constant"><span>Molecular formula <strong>${c.formula}</strong></span><span>${Object.entries(counts(c)).map(([s,n])=>`${s}: ${n}`).join(' · ')} <small>— unchanged</small></span></div><div class="gf-stage"><svg id="gf-svg-${i}" viewBox="0 0 660 440" role="group" aria-label="Slide ${c.label} horizontally through all marked positions"></svg></div><p id="gf-state-${i}" class="gf-state" aria-live="polite"></p><div class="gf-positions" role="group" aria-label="Group position">${c.states.map((_,j)=>`<button type="button" id="gf-position-${i}-${j}" aria-pressed="${j===c.initial}">Position ${j+1}</button>`).join('')}</div><p class="gf-drag-hint">Slide the red-outlined ${c.label} to any marked position. Use ← / → when the group is focused.</p><div class="gf-actions"><button type="button" id="gf-reset-${i}">Reset molecule</button></div></section>`).join('');
function render(i){const c=cases[i],f=frame(c,values[i]),member=new Set(c.group);let svg=`<title>${f.settled?f.name:'Rearranging the model'}</title><desc>All positions keep three carbons and the same molecular formula, ${c.formula}. Drag the red outline horizontally.</desc>`;
for(const {edge:[a,b,n],opacity,changing} of f.bonds){if(opacity<.01)continue;const p=f.positions[a],q=f.positions[b],dx=q[0]-p[0],dy=q[1]-p[1],len=Math.hypot(dx,dy);if(len<42)continue;const ux=dx/len,uy=dy/len;for(let j=0;j<n;j++){const d=(j-(n-1)/2)*7;svg+=`<line x1="${p[0]+21*ux-d*uy}" y1="${p[1]+21*uy+d*ux}" x2="${q[0]-21*ux-d*uy}" y2="${q[1]-21*uy+d*ux}" class="gf-bond ${changing&&!f.settled?'changing':''}" opacity="${opacity}" ${member.has(a)&&member.has(b)?`data-movable="${i}"`:''}/>`;}}
c.states.forEach((s,j)=>{const x=s.positions[c.group[0]][0];svg+=`<path d="M${x} 392v10" class="gf-position-mark"/><text x="${x}" y="421" class="gf-position-number">${j+1}</text>`;});
const points=c.group.map(j=>f.positions[j]),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,rx=(Math.max(...xs)-Math.min(...xs))/2+38,ry=(Math.max(...ys)-Math.min(...ys))/2+40;
svg+=`<g class="gf-movable" data-movable="${i}" role="slider" tabindex="0" aria-label="Move ${c.label} horizontally" aria-valuemin="1" aria-valuemax="${c.states.length}" aria-valuenow="${(values[i]+1).toFixed(2)}" aria-valuetext="${f.settled?'Position '+(Math.round(values[i])+1)+': '+f.name:'Moving between positions'}"><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" class="gf-red-outline"/></g>`;
// Plain atom labels: only the whole movable group receives an outline.
c.symbols.map((s,j)=>({s,j})).sort((a,b)=>Number(member.has(a.j))-Number(member.has(b.j))).forEach(({s,j})=>{const [x,y]=f.positions[j];svg+=`<text x="${x}" y="${y}" class="gf-plain-atom gf-plain-${s}" ${member.has(j)?`data-movable="${i}"`:''}>${s}</text>`;});document.getElementById('gf-svg-'+i).innerHTML=svg;document.getElementById('gf-state-'+i).textContent=f.settled?f.name:'Rearranging the model · same formula';c.states.forEach((_,j)=>document.getElementById('gf-position-'+i+'-'+j).setAttribute('aria-pressed',String(f.settled&&Math.round(values[i])===j)));}
function coordinate(svg,e){const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse()).x;}
function finish(cancel=false){if(!drag)return;const d=drag;drag=null;values[d.i]=cancel?d.start:Math.round(values[d.i]);render(d.i);const svg=document.getElementById('gf-svg-'+d.i);if(svg.hasPointerCapture(d.pointer))svg.releasePointerCapture(d.pointer);}
cases.forEach((c,i)=>{const svg=document.getElementById('gf-svg-'+i);svg.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0||!e.target.closest('[data-movable]'))return;e.preventDefault();const start=values[i];drag={i,start,pointer:e.pointerId,offset:frame(c,start).positions[c.group[0]][0]-coordinate(svg,e)};svg.setPointerCapture(e.pointerId);});svg.addEventListener('pointermove',e=>{if(!drag||drag.i!==i||drag.pointer!==e.pointerId)return;e.preventDefault();values[i]=dragValue(c,coordinate(svg,e)+drag.offset);render(i);});svg.addEventListener('pointerup',e=>{if(drag&&drag.pointer===e.pointerId)finish();});svg.addEventListener('pointercancel',()=>finish(true));svg.addEventListener('keydown',e=>{if(!e.target.closest('[data-movable]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();values[i]=e.key==='Home'?0:e.key==='End'?c.states.length-1:Math.max(0,Math.min(c.states.length-1,Math.round(values[i])+(e.key==='ArrowRight'?1:-1)));render(i);svg.querySelector('[role="slider"]').focus();});c.states.forEach((_,j)=>document.getElementById('gf-position-'+i+'-'+j).addEventListener('click',()=>{finish(true);values[i]=j;render(i);}));document.getElementById('gf-reset-'+i).addEventListener('click',()=>{finish(true);values[i]=c.initial;render(i);});document.getElementById('gf-mode-'+i).addEventListener('click',()=>{finish(true);cases.forEach((_,j)=>{document.getElementById('gf-panel-'+j).hidden=j!==i;document.getElementById('gf-mode-'+j).setAttribute('aria-pressed',String(j===i));});});render(i);});
})();
